#!/usr/bin/env python3
"""Standalone host-OS-policy / CIDR helper.

Mirrors the behaviour of Suricata's util-cidr.c (CIDRFromMask, CIDRGet,
CIDRGetIPv6) and util-host-os-info.c (SCHInfoAddHostOSInfo,
SCHInfoLoadFromConfig, SCHInfoGetHostOSFlavour) without needing the engine.

Subcommands:
  cidr ipv4-mask <dotted-quad>   -> CIDRFromMask() as a decimal int (-1 if not a prefix)
  cidr ipv4-prefix <n>           -> %08x of the uint32 CIDRGet() returns
  cidr ipv6-prefix <n>           -> the 16 bytes CIDRGetIPv6() fills, as hex
  load <yaml-path>               -> read IPs on stdin, print "<ip> <flavour>"
"""

import socket
import sys

# stream-tcp-reassemble.h: OS_POLICY_NONE = 1, then in declaration order.
# Mirrors sc_hinfo_os_policy_map[] in util-host-os-info.c; the order here is the
# map's order, so the first name for a value is the canonical one.
OS_POLICY_MAP = (
    ("none", 1),
    ("bsd", 2),
    ("bsd-right", 3),
    ("old-linux", 4),
    ("linux", 5),
    ("old-solaris", 6),
    ("solaris", 7),
    ("hpux10", 8),
    ("hpux11", 9),
    ("irix", 10),
    ("macos", 11),
    ("windows", 12),
    ("vista", 13),
    ("windows2k3", 14),
)


def map_enum_name_to_value(name):
    """SCMapEnumNameToValue(): case-insensitive exact match, -1 when absent."""
    for enum_name, enum_value in OS_POLICY_MAP:
        if enum_name.lower() == name.lower():
            return enum_value
    return -1


def map_enum_value_to_name(value):
    """SCMapEnumValueToName(): first name in the map for that value."""
    for enum_name, enum_value in OS_POLICY_MAP:
        if enum_value == value:
            return enum_name
    return None


def byteswap32(value):
    return int.from_bytes((value & 0xFFFFFFFF).to_bytes(4, "big"), "little")


def ntohl(value):
    """Network-order uint32 -> host-order uint32."""
    if sys.byteorder == "big":
        return value & 0xFFFFFFFF
    return byteswap32(value)


# htonl is its own inverse on both endiannesses.
htonl = ntohl


def cidr_from_mask(netmask):
    """util-cidr.c CIDRFromMask(): netmask is the uint32 in network byte order."""
    netmask = ntohl(netmask)
    if netmask == 0:
        return 0
    p = 0
    seen_1 = False
    while netmask > 0:
        if netmask & 1:
            seen_1 = True
            p += 1
        elif seen_1:
            return -1
        netmask >>= 1
    return p


def cidr_get(cidr):
