/* Oracle: the real CIDR functions copied verbatim from /app/src/util-cidr.c,
 * compiled standalone so the Python port can be diffed against them. */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/in.h>

int CIDRFromMask(uint32_t netmask)
{
    netmask = ntohl(netmask);
    if (netmask == 0) {
        return 0;
    }
    int p = 0;
    bool seen_1 = false;
    while (netmask > 0) {
        if (netmask & 1) {
            seen_1 = true;
            p++;
        } else {
            if (seen_1) {
                return -1;
            }
        }
        netmask >>= 1;
    }
    return p;
}

uint32_t CIDRGet(int cidr)
{
    if (cidr <= 0 || cidr > 32)
        return 0;
    uint32_t netmask = htonl(0xFFFFFFFF << (32UL - (uint32_t)cidr));
    return netmask;
}

void CIDRGetIPv6(int cidr, struct in6_addr *in6)
{
    int i = 0;

    memset(in6, 0, sizeof(struct in6_addr));

    while (cidr > 8) {
        in6->s6_addr[i] = 0xff;
        cidr -= 8;
        i++;
    }

    while (cidr > 0) {
        in6->s6_addr[i] |= 0x80;
        if (--cidr > 0)
            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

int main(int argc, char **argv)
{
    if (argc != 3)
        return 2;

    if (strcmp(argv[1], "ipv4-mask") == 0) {
        struct in_addr in;
        if (inet_pton(AF_INET, argv[2], &in) <= 0)
            return 1;
        printf("%d\n", CIDRFromMask(in.s_addr));
        return 0;
    }
    if (strcmp(argv[1], "ipv4-prefix") == 0) {
        printf("%08x\n", CIDRGet(atoi(argv[2])));
        return 0;
    }
    if (strcmp(argv[1], "ipv6-prefix") == 0) {
        struct in6_addr in6;
        CIDRGetIPv6(atoi(argv[2]), &in6);
        for (int i = 0; i < 16; i++)
            printf("%02x", in6.s6_addr[i]);
        printf("\n");
        return 0;
    }
    return 2;
}

