            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

int main(int argc, char **argv)
{
    if (argc != 3)
        return 2;

    if (strcmp(argv[1], "ipv4-mask") == 0) {
        struct in_addr in;
        if (inet_pton(AF_INET, argv[2], &in) <= 0)
            return 1;
        printf("%d\n", CIDRFromMask(in.s_addr));
        return 0;
    }
    if (strcmp(argv[1], "ipv4-prefix") == 0) {
        printf("%08x\n", CIDRGet(atoi(argv[2])));
        return 0;
    }
    if (strcmp(argv[1], "ipv6-prefix") == 0) {
        struct in6_addr in6;
        CIDRGetIPv6(atoi(argv[2]), &in6);
        for (int i = 0; i < 16; i++)
            printf("%02x", in6.s6_addr[i]);
        printf("\n");
        return 0;
    }
    return 2;
}

