/* Support routines the real radix sources call, implemented to match the
 * upstream semantics closely enough for the add/lookup paths under test. */
#include "suricata-common.h"

__thread SCError sc_errno = SC_OK;

size_t strlcpy(char *dst, const char *src, size_t siz)
{
    size_t slen = strlen(src);
    if (siz != 0) {
        size_t copy = (slen >= siz) ? siz - 1 : slen;
        memcpy(dst, src, copy);
        dst[copy] = '\0';
    }
    return slen;
}

/* util-byte.c StringParseU8RangeCheck: strict decimal parse plus range check.
 * Returns the number of bytes consumed on success, <= 0 on error. */
int StringParseU8RangeCheck(
        uint8_t *res, int base, size_t len, const char *str, uint8_t min, uint8_t max)
{
    if (str == NULL)
        return -1;

    /* skip leading space, as strtoull would */
    const char *p = str;
    while (*p == ' ' || *p == '\t')
        p++;
    if (*p == '\0')
        return -1;
    if (*p == '-' || *p == '+')
        return -1; /* upstream rejects signed input for unsigned parsers */

    char *endptr = NULL;
    errno = 0;
    unsigned long long int val = strtoull(p, &endptr, base);
    if (errno == ERANGE)
        return -1;
    if (endptr == p)
        return -1;
    if (len == 0) {
        /* whole string must be consumed */
        if (*endptr != '\0')
            return -1;
    }
    if (val > UINT8_MAX)
        return -1;
    if (val < min || val > max)
        return -1;

    *res = (uint8_t)val;
    return (int)(endptr - str);
}

void PrintInet(int family, const void *src, char *dst, socklen_t size)
{
    if (inet_ntop(family, src, dst, size) == NULL)
        snprintf(dst, size, "<bad>");
}

/* Verbatim from /app/src/util-cidr.c (needed by util-radix6-tree.c). */
void CIDRGetIPv6(int cidr, struct in6_addr *in6)
{
    int i = 0;

    memset(in6, 0, sizeof(struct in6_addr));

    while (cidr > 8) {
        in6->s6_addr[i] = 0xff;
        cidr -= 8;
        i++;
    }

    while (cidr > 0) {
        in6->s6_addr[i] |= 0x80;
        if (--cidr > 0)
            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

