/* Minimal stand-in for Suricata's suricata-common.h, just enough to compile
 * src/util-radix4-tree.c and src/util-radix6-tree.c unmodified (UNITTESTS off).
 * Placed on the include path ahead of /app/src so the real headers' own
 * #include "suricata-common.h" resolves here. */
#ifndef SHIM_SURICATA_COMMON_H
#define SHIM_SURICATA_COMMON_H

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <strings.h>
#include <errno.h>
#include <limits.h>
#include <inttypes.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>

#define SCMalloc(s)     malloc((s))
#define SCCalloc(n, s)  calloc((n), (s))
#define SCFree(p)       free((p))
#define SCStrdup(s)     strdup((s))
#define SCRealloc(p, s) realloc((p), (s))

#define SCMemcmp(a, b, n) memcmp((a), (b), (n))

#define SCLogDebug(...)
#define SCLogError(...)
#define SCLogWarning(...)
#define SCLogNotice(...)
#define SCLogInfo(...)
#define SCLogPerf(...)

#define BUG_ON(x)                                                                                  \
    do {                                                                                           \
        if (x) {                                                                                   \
            fprintf(stderr, "BUG_ON at %s:%d\n", __FILE__, __LINE__);                              \
            abort();                                                                               \
        }                                                                                          \
    } while (0)
#define DEBUG_VALIDATE_BUG_ON(x)

#define BIT_U8(n)  ((uint8_t)(1 << (n)))
#define BIT_U32(n) ((uint32_t)(1UL << (n)))
#define BIT_U64(n) ((uint64_t)(1ULL << (n)))

#ifndef MIN
#define MIN(a, b) (((a) < (b)) ? (a) : (b))
#endif
#ifndef MAX
#define MAX(a, b) (((a) > (b)) ? (a) : (b))
#endif

#define likely(x)   (x)
#define unlikely(x) (x)

/* sc_errno / SCError, as used by the radix add/remove paths */
typedef enum {
    SC_OK = 0,
    SC_EINVAL,
    SC_ENOMEM,
    SC_EEXIST,
    SC_ENOENT,
    SC_ELIMIT,
} SCError;
extern __thread SCError sc_errno;

size_t strlcpy(char *dst, const char *src, size_t siz);
int StringParseU8RangeCheck(
        uint8_t *res, int base, size_t len, const char *str, uint8_t min, uint8_t max);
void PrintInet(int family, const void *src, char *dst, socklen_t size);

#endif /* SHIM_SURICATA_COMMON_H */

/* Support routines the real radix sources call, implemented to match the
 * upstream semantics closely enough for the add/lookup paths under test. */
#include "suricata-common.h"

__thread SCError sc_errno = SC_OK;

size_t strlcpy(char *dst, const char *src, size_t siz)
{
    size_t slen = strlen(src);
    if (siz != 0) {
        size_t copy = (slen >= siz) ? siz - 1 : slen;
        memcpy(dst, src, copy);
        dst[copy] = '\0';
    }
    return slen;
}

/* util-byte.c StringParseU8RangeCheck: strict decimal parse plus range check.
 * Returns the number of bytes consumed on success, <= 0 on error. */
int StringParseU8RangeCheck(
        uint8_t *res, int base, size_t len, const char *str, uint8_t min, uint8_t max)
{
    if (str == NULL)
        return -1;

    /* skip leading space, as strtoull would */
    const char *p = str;
    while (*p == ' ' || *p == '\t')
        p++;
    if (*p == '\0')
        return -1;
    if (*p == '-' || *p == '+')
        return -1; /* upstream rejects signed input for unsigned parsers */

    char *endptr = NULL;
    errno = 0;
    unsigned long long int val = strtoull(p, &endptr, base);
    if (errno == ERANGE)
        return -1;
    if (endptr == p)
        return -1;
    if (len == 0) {
        /* whole string must be consumed */
        if (*endptr != '\0')
            return -1;
    }
    if (val > UINT8_MAX)
        return -1;
    if (val < min || val > max)
        return -1;

    *res = (uint8_t)val;
    return (int)(endptr - str);
}

void PrintInet(int family, const void *src, char *dst, socklen_t size)
{
    if (inet_ntop(family, src, dst, size) == NULL)
        snprintf(dst, size, "<bad>");
}

/* Verbatim from /app/src/util-cidr.c (needed by util-radix6-tree.c). */
void CIDRGetIPv6(int cidr, struct in6_addr *in6)
{
    int i = 0;

    memset(in6, 0, sizeof(struct in6_addr));

    while (cidr > 8) {
        in6->s6_addr[i] = 0xff;
        cidr -= 8;
        i++;
    }

    while (cidr > 0) {
        in6->s6_addr[i] |= 0x80;
        if (--cidr > 0)
            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

/* Verbatim from /app/src/util-ip.c */
void MaskIPNetblock(uint8_t *stream, int netmask, int key_bitlen)
{
    uint32_t mask = 0;
    int i = 0;
    int bytes = key_bitlen / 8;

    for (i = 0; i < bytes; i++) {
        mask = UINT_MAX;
        if (((i + 1) * 8) > netmask) {
            if (((i + 1) * 8 - netmask) < 8)
