static int MapNameToValue(const char *name)
{
    for (EnumCharMap *t = os_policy_map; t->name != NULL; t++) {
        if (strcasecmp(t->name, name) == 0)
            return t->value;
    }
    return -1;
}

static const char *MapValueToName(int value)
{
    for (EnumCharMap *t = os_policy_map; t->name != NULL; t++) {
        if (t->value == value)
            return t->name;
    }
    return NULL;
}

static SCRadix4Tree tree4 = SC_RADIX4_TREE_INITIALIZER;
static SCRadix6Tree tree6 = SC_RADIX6_TREE_INITIALIZER;

static void FreeUD(void *d)
{
    if (d != NULL)
        free(d);
}
static const SCRadix4Config cfg4 = { FreeUD, NULL };
static const SCRadix6Config cfg6 = { FreeUD, NULL };

/* SCHInfoAddHostOSInfo, verbatim in structure */
static int AddHostOSInfo(const char *host_os, const char *host_os_ip_range, int is_ipv4)
{
    char *ip_str = NULL;
    char *ip_str_rem = NULL;
    int *user_data = NULL;
    bool recursive = false;

    if (host_os == NULL || host_os_ip_range == NULL || strlen(host_os_ip_range) == 0)
        return -1;

    int v = MapNameToValue(host_os);
    if (v == -1)
        return -1;
    user_data = malloc(sizeof(int));
    *user_data = v;

    if (strcasecmp(host_os_ip_range, "default") == 0) {
        if (is_ipv4)
            host_os_ip_range = "0.0.0.0/0";
        else
            host_os_ip_range = "::/0";
    }

    ip_str = strdup(host_os_ip_range);

    if ((ip_str_rem = strchr(ip_str, ',')) != NULL) {
        ip_str_rem[0] = '\0';
        ip_str_rem++;
        recursive = true;
    }

    if (strchr(ip_str, ':') == NULL) {
        if (!SCRadix4AddKeyIPV4String(&tree4, &cfg4, ip_str, user_data)) {
            if (sc_errno == SC_EEXIST) {
                fprintf(stderr, "duplicate\n");
                exit(1);
            }
            fprintf(stderr, "invalid ipv4 address '%s'\n", ip_str);
            FreeUD(user_data);
            free(ip_str);
            return -1;
        }
    } else {
        if (!SCRadix6AddKeyIPV6String(&tree6, &cfg6, ip_str, user_data)) {
            if (sc_errno == SC_EEXIST) {
                fprintf(stderr, "duplicate\n");
                exit(1);
            }
            fprintf(stderr, "invalid ipv6 address '%s'\n", ip_str);
            FreeUD(user_data);
            free(ip_str);
            return -1;
        }
    }

    if (recursive) {
        if (AddHostOSInfo(host_os, ip_str_rem, is_ipv4) == -1) {
            free(ip_str);
            return -1;
        }
    }

    free(ip_str);
    return v;
}

/* SCHInfoGetHostOSFlavour, verbatim */
static int GetHostOSFlavour(const char *str)
{
    void *user_data = NULL;

    if (str == NULL || strchr(str, '/') != NULL)
        return -1;

    if (strchr(str, ':') != NULL) {
        struct in6_addr addr;
        if (inet_pton(AF_INET6, str, &addr) <= 0)
            return -1;
        (void)SCRadix6TreeFindBestMatch(&tree6, (uint8_t *)&addr.s6_addr, &user_data);
        if (user_data == NULL)
            return -1;
        return *((int *)user_data);
    } else {
        struct in_addr addr;
        if (inet_pton(AF_INET, str, &addr) <= 0)
            return -1;
        (void)SCRadix4TreeFindBestMatch(&tree4, (uint8_t *)&addr.s_addr, &user_data);
        if (user_data == NULL)
            return -1;
        return *((int *)user_data);
    }
}

int main(int argc, char **argv)
{
    for (int i = 1; i < argc; i++) {
        char *spec = strdup(argv[i]);
        char *eq = strchr(spec, '=');
        if (eq == NULL) {
            fprintf(stderr, "bad spec '%s'\n", argv[i]);
            return 2;
        }
        *eq = '\0';
        const char *flavour = spec;
        const char *range = eq + 1;
        int is_ipv4 = (strchr(range, ':') != NULL) ? 0 : 1;
        if (AddHostOSInfo(flavour, range, is_ipv4) == -1) {
            fprintf(stderr, "add failed: %s\n", argv[i]);
            return 1;
        }
        free(spec);
    }

    char line[512];
    while (fgets(line, sizeof(line), stdin) != NULL) {
        size_t n = strlen(line);
        while (n > 0 && (line[n - 1] == '\n' || line[n - 1] == '\r' || line[n - 1] == ' ' ||
                                line[n - 1] == '\t'))
            line[--n] = '\0';
        char *s = line;
        while (*s == ' ' || *s == '\t')
            s++;
        if (*s == '\0')
            continue;
        int v = GetHostOSFlavour(s);
        const char *name = (v == -1) ? "none" : MapValueToName(v);
        if (name == NULL)
            name = "none";
        printf("%s %s\n", s, name);
    }
    return 0;
}

