        if (is_ipv4)
            host_os_ip_range = "0.0.0.0/0";
        else
            host_os_ip_range = "::/0";
    }

    if ( (ip_str = SCStrdup(host_os_ip_range)) == NULL) {
        FatalError("Error allocating memory");
    }

    /* check if we have more addresses in the host_os_ip_range */
    if ((ip_str_rem = strchr(ip_str, ',')) != NULL) {
        ip_str_rem[0] = '\0';
        ip_str_rem++;
        recursive = true;
    }

