                SCLogError("invalid ipv6 address '%s'", ip_str);
            }
            SCHInfoFreeUserDataOSPolicy(user_data);
            SCFree(ip_str);
            return -1;
        }
    }

    if (recursive) {
        SCHInfoAddHostOSInfo(host_os, ip_str_rem, is_ipv4);
    }

    SCFree(ip_str);
    return *user_data;
}

